const range = new Proxy({ min: 1, max: 100 }, {
  has(target, prop) {
    const num = Number(prop)
    return !isNaN(num) && num >= target.min && num <= target.max
  }
})
return {
  has50: 50 in range,
  has150: 150 in range,
  hasName: "name" in range
}
